%[text] # A single circular wire loop  with current
clear;

syms  q  real 
syms t c epsilon0 mu0 theta real positive
syms x r z v_o real 
syms c_x c_y real 
syms vp_x vp_y real 


assumeAlso (r > 0)
assumeAlso (t > 0)
assumeAlso (z > 0)
assumeAlso (c > 0)
assumeAlso (v_o > 0)
assumeAlso (c_x > 0)
assumeAlso (c_y < 0)
assumeAlso (vp_x > 0)
assumeAlso (vp_y > 0)
assumeAlso (c - v_o > 0)
assumeAlso (c - vp_x > 0)
assumeAlso (c - vp_y > 0)
assumeAlso (c^2 - v_o^2 > 0)
assumeAlso (c^2 - vp_y^2 - vp_y^2 > 0)



% Define the position of the space where the force will be measured
r_p = [0, 0, 0];

% The velocity of the charged particle at r_p

vp = [vp_x,vp_y,0];



%%
%[text] ## Solving for the light vector reaching the charge at r\_p
% The circular loop will centered at x=[0,0,0] with a radius r in the x-y
% plane
% Light vector leaving the wire
cv = [c_x, c_y, 0];

%arbritary point in the wire

r_w = r*[-1,0,0];

% the velocity of the wire charges counter clockwise
v_w = v_o*[0,1,0];

% the light wire reaching the measurement point
eq_1 = r_w + (v_w+cv)*t - r_p == [0,0,0] %[output:95a43709]
eq_2 = dot(cv,cv)-c^2==0 %[output:872aee0e]

[ccx,ccy,tt,par,cond] = solve([eq_1(1),eq_1(2),eq_2],[c_x,c_y,t],"IgnoreAnalyticConstraints",true,ReturnConditions=true);

cc_x = simplify(expand(ccx(1)),'IgnoreAnalyticConstraints',true,'Criterion','preferReal','Steps',100), cc_y = simplify(ccy(1)),tt = simplify(tt(1),'IgnoreAnalyticConstraints',true,'Criterion','preferReal','Steps',100) %[output:42683369] %[output:654436d9] %[output:4bdcbd59]
%%
RotA = [cos(theta),-sin(theta),0;sin(theta),cos(theta),0;0,0,0]';
% Calculate data at point in loop
rt_w = [r,0,0]*RotA %[output:83ec499f]
dRotA = diff(RotA,theta);
vt_w = [v_o,0,0]*dRotA %[output:42904317]
cvec = [-cc_x,cc_y,0]*RotA %[output:0a719249]
angles = [0,pi/2,pi,7*pi/4];
plotrange=[0,2*pi];
posx=subs(rt_w,r,1);

figure(1) %[output:27ea08d5]
fplot(posx(1),plotrange) %[output:27ea08d5]
hold on %[output:27ea08d5]
posv=subs(vt_w,v_o,1);
fplot(posv(1),plotrange) %[output:27ea08d5]
posc=subs(cvec,[c,v_o],[1,0.001]);

fplot(posc(1),plotrange) %[output:27ea08d5]
hold off %[output:27ea08d5]
clf(1)
%%
%[text] ## The Point Force
%[text] 
k_e = q^2/(4*pi*epsilon0);
R2 = r^2;

vprel = vt_w - vp;
v_rel1 = cvec + vt_w;
ov = cvec/c;
v_rel1m = dot(v_rel1,v_rel1);

v_rel2 = cvec + vt_w - vp;
v_rel2m = dot(v_rel2,v_rel2);


cmag = simplify(sqrt(v_rel1m),'Criterion','preferReal','Steps',100); %Speed 

p1 = simplify(1/R2,'Criterion','preferReal','Steps',100); % distance factor
p2 = simplify(v_rel1m/c^2,'Criterion','preferReal','Steps',100); % density and velocity correction
p3 = simplify(1.0/dot(v_rel1,ov),'Criterion','preferReal','Steps',100);
p4 = simplify((dot(vp,ov)*vt_w - dot(vp,vt_w)*ov )/c^2,'Criterion','preferReal','Steps',100);
F_a = simplify(p1*p2*p3*(ov+p4),'Criterion','preferReal','Steps',100);


%%
%[text] ## Integrate the static charges
F_n = simplify(subs(F_a,v_o,0),'IgnoreAnalyticConstraints',true,'Criterion','preferReal','Steps',100);
F_n = simplify(taylor(F_n,[vp_x,vp_y],[0,0],order=2),'IgnoreAnalyticConstraints',true,'Criterion','preferReal','Steps',100);
Ft_n = int(F_n,theta,0,2*pi) %[output:4fe53e83]

%%
%[text] ## Integrating the current

F_ct = simplify(taylor(F_a,v_o,0,order=2),'IgnoreAnalyticConstraints',true,'Criterion','preferReal','Steps',100);
F_ct = simplify(taylor(F_ct,[vp_x,vp_y],[0,0],order=2),'IgnoreAnalyticConstraints',true,'Criterion','preferReal','Steps',100);

Ft_c = int(F_ct,theta,0,2*pi) %[output:4060c4f0]

%%
%[text] ## The net force
% The moving corpuscle solution
F_atot = k_e*simplify(Ft_c - Ft_n) %[output:57304b83]
% The Lorentz solution 
sol=[(q^2*v_o*vp_y)/(2*c^2*epsilon0*r^2), -(q^2*v_o*vp_x)/(2*c^2*epsilon0*r^2), sym(0)] %[output:73bf2880]

